def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    rows = data[2:2 + r]
    W = c + 2
    g = bytearray(W * (r + 2))
    for i in range(r):
        base = (i + 1) * W + 1
        row = rows[i]
        for j in range(c):
            if row[j] == '1':
                g[base + j] = 1
    count = 0
    for s in range(len(g)):
        if g[s]:
            count += 1
            g[s] = 0
            queue = [s]
            while queue:
                x = queue.pop()
                for y in (x - 1, x + 1, x - W, x + W):
                    if g[y]:
                        g[y] = 0
                        queue.append(y)
    print(count)

